xquery.xq-expression:

declare variable $employees as node() external;

let $totalEmployees := count($employees//employee)
let $avgSalary := avg($employees//employee/salary)
let $maxSalary := max($employees//employee/salary)
let $minSalary := min($employees//employee/salary)
let $engineeringCount := count($employees//employee[department = "Engineering"])
let $marketingCount := count($employees//employee[department = "Marketing"])
let $salesCount := count($employees//employee[department = "Sales"])
let $excellentCount := count($employees//employee[performance = "Excellent"])
let $goodCount := count($employees//employee[performance = "Good"])

return
<analysis>
    <summary>
        <total_employees>{$totalEmployees}</total_employees>
        <average_salary>{round($avgSalary)}</average_salary>
        <max_salary>{$maxSalary}</max_salary>
        <min_salary>{$minSalary}</min_salary>
    </summary>
    <department_breakdown>
        <engineering>{$engineeringCount}</engineering>
        <marketing>{$marketingCount}</marketing>
        <sales>{$salesCount}</sales>
    </department_breakdown>
    <performance_breakdown>
        <excellent>{$excellentCount}</excellent>
        <good>{$goodCount}</good>
    </performance_breakdown>
</analysis>


declare variable $employees as node() external;

let $totalRecords := count($employees//employee)
let $completeRecords := count($employees//employee[normalize-space(name) != "" and normalize-space(age) != "" and normalize-space(department) != "" and normalize-space(salary) != "" and normalize-space(performance) != ""])
let $incompleteRecords := $totalRecords - $completeRecords
let $dataQualityScore := round(($completeRecords div $totalRecords) * 100)

return
<data_quality_report>
    <total_records>{$totalRecords}</total_records>
    <complete_records>{$completeRecords}</complete_records>
    <incomplete_records>{$incompleteRecords}</incomplete_records>
    <quality_score>{$dataQualityScore}%</quality_score>
    <status>
        {
            if ($dataQualityScore >= 95) then "Excellent"
            else if ($dataQualityScore >= 90) then "Good"
            else if ($dataQualityScore >= 80) then "Fair"
            else "Needs Improvement"
        }
    </status>
</data_quality_report>
